import openpyxl

def load() -> pd.DataFrame:
    xl_file = pd.ExcelFile('data/biomedical/input/1-s2.0-S0092867420301070-mmc1.xlsx')
    sheets = xl_file.sheet_names
    data = []
    for sheet in sheets:
        df = pd.read_excel('data/biomedical/input/1-s2.0-S0092867420301070-mmc1.xlsx', sheet_name=sheet)
        data.append({
            'sheet': sheet,
            'nrows': len(df),
            'ncols': len(df.columns),
            'columns': ', '.join(df.columns.tolist()[:10])
        })
    return pd.DataFrame(data)

def process(load_hyperactivated, get_cnv_high_endometroid) -> pd.DataFrame:
    cnv_high_endo_ids = set(get_cnv_high_endometroid['idx'].values)
    hyperactivated_filtered = load_hyperactivated[load_hyperactivated['sample_id'].isin(cnv_high_endo_ids)]
    return hyperactivated_filtered[['sample_id', 'protein']].drop_duplicates()

def process(hyperactivated_cnv_high_endo, fda_drug_targets):
    hyperactivated = hyperactivated_cnv_high_endo[['protein']].drop_duplicates()
    fda_targets = fda_drug_targets[['gene_name']].drop_duplicates()

    result = hyperactivated[hyperactivated['protein'].isin(fda_targets['gene_name'].values)]
    return result.rename(columns={'protein': 'gene_name'})
